command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: ROTER SCHIMMER (Ausführung - Universell)
// ==========================================

(async () => {
    // --- 1. FRAMEWORK LADEN ---
    const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) { await fwMacro.execute(); }

    const DSK_FW = globalThis.DSK || DSK;
    if (typeof DSK_FW === "undefined") return ui.notifications.error("Luna sagt 🌙: Framework fehlt!");

    if (DSK_FW.EffektEnde && !globalThis._dskRoterSchimmerEndeRegistered) {
        globalThis._dskRoterSchimmerEndeRegistered = true;
        // Meldet sich bei allen Effekten, die "Roter Schimmer" heißen
        DSK_FW.EffektEnde.Register("roterSchimmer", "Roter Schimmer", "Der rote Lichtpunkt erlischt und der Jagdinstinkt aller Betroffenen beruhigt sich wieder.");
    }

    const getOwners = (act) => Object.entries(act?.ownership || {}).filter(([id, lvl]) => lvl === 3 && id !== "default").map(([id]) => id);

    // --- 2. WILLENSKRAFT-WÄCHTER & CLEANUP-HOOK ---
    if (!globalThis.DSK_RoterSchimmerWillenskraftHook) {
        globalThis.DSK_RoterSchimmerWillenskraftHook = true;
        Hooks.on("createChatMessage", async (msg) => {
            if (msg.user.id !== game.user.id) return;
            const content = (msg.content || "").toLowerCase();
            const flavor = (msg.flavor || "").toLowerCase();

            if (content.includes("willenskraft") || flavor.includes("willenskraft")) {
                const speaker = msg.speaker;
                let rollActor = game.actors.get(speaker.actor);
                if (!rollActor && speaker.token) rollActor = canvas.scene.tokens.get(speaker.token)?.actor;
                if (!rollActor) return;

                const hatJagdfieberEffekt = rollActor.effects.some(e => {
                    const n = (e.name || e.label || "").toLowerCase();
                    return n.includes("roter schimmer") && n.includes("jagdfieber");
                });

                if (hatJagdfieberEffekt) {
                    const hatJagdfieberEigenschaft = rollActor.items.some(i => (i.name || "").toLowerCase().includes("jagdfieber"));
                    if (hatJagdfieberEigenschaft) {
                        let whisperTargets = [...new Set([...game.users.filter(u => u.isGM).map(u => u.id), ...getOwners(rollActor)])].filter(id => game.users.get(id));
                        await ChatMessage.create({
                            whisper: whisperTargets, speaker: { alias: "System" },
                            content: `
                                <div style="font-family: 'Signika', sans-serif;">
                                    <div class="dskbox1">
                                        <p style="font-weight:bold; margin-top:6px; margin-bottom:0;">Jagdfieber blockiert Probe!</p>
                                    </div>
                                    <div class="dskbox2" style="margin-top:10px; text-align: center;">
                                        <p style="color:#000; font-weight:bold; font-size:1.1em;">${rollActor.name}</p>
                                        <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                                        <p style="margin-bottom: 8px;">Da das Ziel unter dem Einfluss des <b>Roten Schimmers</b> steht und die Eigenschaft <b>Jagdfieber</b> besitzt, wird der Instinkt übermächtig!</p>
                                        <p style="color:#8b0000; font-weight:bold;">Die Probe darf nicht abgelegt werden und gilt als automatisch gescheitert.</p>
                                    </div>
                                </div>
                            `
                        });
                    }
                }
            }
        });
    }

    if (!globalThis.DSK_RoterSchimmerCleanup) {
        globalThis.DSK_RoterSchimmerCleanup = true;
        Hooks.on("deleteActiveEffect", async (effect) => {
            if (!game.user.isGM) return;
            const effName = effect.name || effect.label || "";

            // 🚩 HIER ist die Kette: Wenn der Haupt-Effekt beim Wirkenden gelöscht wird!
            if (effName.includes("Roter Schimmer") && !effName.includes("Jagdfieber")) {
                const tId = effect.getFlag("dsk", "templateId");
                if (tId) {
                    const doc = canvas.scene.templates.get(tId);
                    if (doc) await doc.delete();
                }

                const casterUuid = effect.parent.uuid;
                for (let t of canvas.tokens.placeables) {
                    if (!t.actor) continue;
                    const toDelete = t.actor.effects.filter(e => {
                        const n = e.name || e.label || "";
                        return n.includes("Roter Schimmer") && n.includes("Jagdfieber") && e.getFlag("dsk", "sourceCasterUuid") === casterUuid;
                    }).map(e => e.id);

                    if (toDelete.length > 0) {
                        setTimeout(async () => {
                            await t.actor.deleteEmbeddedDocuments("ActiveEffect", toDelete);
                        }, 100);
                    }
                }
            }
        });
    }

    // --- 3. CASTER ERMITTELN & AHNE AUS PROFESSION LESEN ---
    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character;
    if (!casterActor) casterActor = game.actors.find(a => a.getFlag("world", "letzteGabenQS") !== undefined);

    // Falls über Chatbutton (Zustand B) -> Caster am Aktiv-Effekt erkennen (Der ohne "Jagdfieber" im Namen)
    if (!casterActor) casterActor = game.actors.find(a => a.effects.some(e => {
        const n = e.name || e.label || "";
        return n.includes("Roter Schimmer") && !n.includes("Jagdfieber");
    }));

    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");

    const profession = (casterActor.system?.details?.profession || "").toLowerCase();
    const ahne = profession.includes("aphasma") ? "Aphasma" : "Zerzal";

    const gabenName = "Roter Schimmer";
    const finalEffektName = `${gabenName} (${ahne})`; // Standard-Benennung für den Caster
    const zielEffektName = `${gabenName} (${ahne}) - Jagdfieber`; // Standard-Benennung für die Ziele
    const iconBild = DSK_FW.Symbol(ahne);

    // --- 4. ZUSTANDS-MASCHINE (STATE A oder B?) ---
    const qsWert = Number(casterActor.getFlag("world", "letzteGabenQS"));
    const isActivation = !isNaN(qsWert) && qsWert > 0;

    if (isActivation) {
        // ========================================================
        // 🔴 STATE A: SCHABLONE PLATZIEREN & CASTER AKTIVIEREN
        // ========================================================
        const dauerKR = qsWert * 5;
        const alteMessageId = casterActor.getFlag("world", "letzteGabenMessageId");

        let casterToken = casterActor.getActiveTokens()[0] || canvas.tokens.controlled[0];
        if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Du brauchst einen Token auf der Karte für das Licht!");

        const templateData = {
            t: "circle", user: game.user.id, distance: 0.3, // 🚩 HIER: Der kleinere Radius von 0.3 Schritt!
            x: casterToken.center.x, y: casterToken.center.y,
            fillColor: "#ff0000", fillAlpha: 0.6, lineThickness: 2,
            flags: { dsk: { isRoterSchimmer: true } }
        };

        const createdTemplates = await canvas.scene.createEmbeddedDocuments("MeasuredTemplate", [templateData]);
        let templateDoc = createdTemplates[0];

        ui.notifications.info("Luna sagt 🌙: Platziere den roten Punkt (max. 8 Schritt entfernt).");

        const confirmPosition = async () => {
            return await foundry.applications.api.DialogV2.wait({
                window: { title: "Roten Schimmer platzieren" },
                position: { width: 420 },
                content: `<div style="font-family: 'Signika', sans-serif;">${DSK_FW.UI.Header(finalEffektName, iconBild)}<div class="dskbox2" style="margin-top:10px;"><p>Bewege die rote Markierung an die gewünschte Position.<br><br><b>Achtung:</b> Der Punkt darf maximal 8 Schritt entfernt sein!</p></div></div>`,
                buttons: [
                    { action: "ok", label: "Position Bestätigen", icon: "fas fa-check", default: true, callback: () => true },
                    { action: "cancel", label: "Abbrechen", icon: "fas fa-times", callback: () => false }
                ],
                rejectClose: false
            });
        };

        try { canvas.templates.activate(); } catch (e) {}
        const isConfirmed = await confirmPosition();
        try { canvas.tokens.activate(); } catch (e) {}

        if (!isConfirmed) {
            await templateDoc.delete();
            return ui.notifications.warn("Luna sagt 🌙: Aktivierung abgebrochen.");
        }

        await casterActor.unsetFlag("world", "letzteGabenQS");
        await casterActor.unsetFlag("world", "letzteGabenMessageId");

        let alterEffekt = casterActor.effects.find(e => (e.name || e.label) === finalEffektName);
        if (alterEffekt) await alterEffekt.delete();

        await casterActor.createEmbeddedDocuments("ActiveEffect", [{
            name: finalEffektName, icon: iconBild, img: iconBild, duration: { rounds: dauerKR },
            description: `Konzentriert sich auf einen roten Lichtpunkt. Kann Ziele in der Nähe damit zum Spielen verführen (QS ${qsWert}).`,
            flags: { dsk: { qs: qsWert, templateId: templateDoc.id } }
        }]);

        const buttonMacroLink = `@UUID[Compendium.dsk-havena-und-umland.makros.Macro.oas2dw4CZKTOW0ml]{Gabe anwenden}`;
        const successContent = `
            <div style="font-family: 'Signika', sans-serif;">
                ${DSK_FW.UI.Header(finalEffektName, iconBild)}
                <div class="dskbox2" style="margin-top:10px;">
                    <p>Ein kleiner, roter Lichtpunkt entsteht an der gedeuteten Stelle und tanzt über den Boden.</p>
                    <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                    <p style="margin-bottom: 8px; font-size: 0.95em; color: #555;">
                        <b>Info an GM:</b> Klicke den Spieler mit dem Fokus-Effekt an, nimm das Ziel (oder die Ziele) ins Target und klicke dann auf den Button:
                    </p>
                    <p style="text-align:center;">
                        <span style="font-size: 15px;">${buttonMacroLink}</span>
                    </p>
                    <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                    <p style="text-align:center; font-weight:bold;">Wirkungsdauer: ${dauerKR} KR <span style="font-weight:300; font-size:0.9em; opacity:0.8;">(${qsWert} QS x 5)</span></p>
                </div>
            </div>
        `;

        let msg = alteMessageId ? game.messages.get(alteMessageId) : null;
        if (msg) await msg.update({ content: successContent });
        else await ChatMessage.create({ content: successContent, speaker: { alias: "System" } });

    } else {
        // ========================================================
        // 🐾 STATE B: JAGDFIEBER PRÜFEN & MEHRERE ZIELE VERFÜHREN
        // ========================================================
        const casterEffekt = casterActor.effects.find(e => (e.name || e.label) === finalEffektName);
        if (!casterEffekt) return ui.notifications.warn("Luna sagt 🌙: Dein roter Schimmer ist nicht mehr aktiv! Wirk die Gabe neu.");

        const activeQs = casterEffekt.getFlag("dsk", "qs") || 1;
        const dauerKR = activeQs * 5;
        const willenskraftMalus = activeQs * 2;

        const targets = Array.from(game.user.targets);
        if (targets.length === 0) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst ein oder mehrere Ziele (Targets) aus!");

        let affectedNames = [];
        let jagdfieberNames = [];

        for (let targetToken of targets) {
            const targetActor = targetToken.actor;
            if (!targetActor) continue;

            if (!DSK_FW.Wesen.match(targetActor, ["erwacht", "erwachter", "erwachte", "tier", "tiere", "katze", "katzen"])) {
                ui.notifications.warn(`Luna sagt 🌙: ${targetActor.name} ist ungeeignet und wird ignoriert.`);
                continue;
            }

            const hatJagdfieber = targetActor.items.some(i => (i.name || "").toLowerCase().includes("jagdfieber"));
            if (hatJagdfieber) jagdfieberNames.push(targetActor.name);
            affectedNames.push(targetActor.name);

            let alterZielEffekt = targetActor.effects.find(e => (e.name || e.label) === zielEffektName);
            if (alterZielEffekt) await alterZielEffekt.delete();

            await targetActor.createEmbeddedDocuments("ActiveEffect", [{
                name: zielEffektName,
                icon: iconBild,
                img: iconBild,
                duration: { rounds: dauerKR },
                description: `Wird vom roten Schimmer abgelenkt. Willenskraft-Probe um -${willenskraftMalus} erschwert, um den Jagdinstinkt zu ignorieren.`,
                changes: [{ 
                    key: "system.skillModifiers.FW", 
                    mode: 0, 
                    value: `Willenskraft -${willenskraftMalus}`, 
                    priority: 20 
                }],
                flags: { dsk: { ahne: ahne, sourceCasterUuid: casterActor.uuid } }
            }]);

            await new Promise(resolve => setTimeout(resolve, 200));
        }

        if (affectedNames.length === 0) return;

        const thinStyle = 'style="font-weight: 300; font-size: 0.9em; opacity: 0.8;"';
        const hatEinZielJagdfieber = jagdfieberNames.length > 0;

        const jagdfieberBox = hatEinZielJagdfieber ? `
            <div style="background: rgba(139,0,0,0.1); border: 1px solid #8b0000; border-radius: 4px; padding: 6px; margin-bottom: 8px;">
                <p style="color:#8b0000; font-weight:bold; text-align:center; margin-bottom: 5px;">Jagdfieber</p>
                <p style="font-size: 0.9em; margin-bottom: 3px; text-align: center; color: #000;">Folgende Ziele dürfen <b>keine</b> Probe ablegen:</p>
                <ul class="dsklist" style="margin-bottom: 0;">
                    ${jagdfieberNames.map(n => `<li style="font-weight:bold; color:#000;">${n}</li>`).join("")}
                </ul>
            </div>
        ` : "";

        const successContent = `
            <div style="font-family: 'Signika', sans-serif;">
                ${DSK_FW.UI.Header(zielEffektName, iconBild)}
                <div class="dskbox2" style="margin-top:10px;">
                    <p>Das tanzende, rote Licht weckt den Jagdinstinkt in den gewählten Zielen.</p>
                    <ul class="dsklist" style="margin-bottom: 8px;">
                        ${affectedNames.map(n => `<li><b>${n}</b></li>`).join("")}
                    </ul>
                    <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                    <p style="margin-bottom: 8px;">
                        Wollen sich die Betroffenen entgegen ihres Instinktes nicht auf das rote Licht stürzen, muss eine um <b>${willenskraftMalus} erschwerte Probe</b> auf <b>Willenskraft</b> abgelegt werden.
                    </p>
                    ${jagdfieberBox}
                    <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                    <p style="text-align:center; font-weight:bold;">Wirkungsdauer:<br>${dauerKR} KR <span ${thinStyle}>(${activeQs} QS x 5)</span></p>
                </div>
            </div>
        `;

        await ChatMessage.create({ content: successContent, speaker: { alias: "System" } });
    }
})();
